import { useState } from 'react';
import { Field } from './Field';
import { Chip } from './Chip';
import { Tag } from './Tag';
import { Button } from './Button';
import './searchHeader.css';

const FILTERS = ['Today', 'This week', 'This month'];

export function SearchHeader({ onSearch, ...rest }) {
  const [query, setQuery] = useState('');
  const [activeFilter, setActiveFilter] = useState('Today');

  return (
    <div className="search-header" {...rest}>
      <Field label="Search" placeholder="Search…" value={query} onChange={(e) => setQuery(e.target.value)} />
      <div className="search-header__filters">
        {FILTERS.map((label) => (
          <span className="search-header__filter" key={label}>
            <Chip Label={label} pressed={activeFilter === label} onClick={() => setActiveFilter(label)} />
            {label === 'Today' && <Tag Label="New" Tone="Positive" />}
          </span>
        ))}
      </div>
      <Button Label="Search" onClick={() => onSearch?.({ query, filter: activeFilter })} />
    </div>
  );
}

