import { useState } from 'react';
import { Field } from './Field';
import { Chip } from './Chip';
import { Tag } from './Tag';
import { Button } from './Button';
import './search-results-header.css';

const FILTERS = ['Today', 'This week', 'This month'];

export function SearchResultsHeader({ onSearch }) {
  const [active, setActive] = useState('Today');

  return (
    <div className="search-results-header">
      <div className="search-results-header__field">
        <Field label="Search" placeholder="Search" />
      </div>
      <div className="search-results-header__filters" role="group" aria-label="Date range">
        {FILTERS.map((label) => {
          const isActive = active === label;
          return (
            <div key={label} className="search-results-header__filter">
              <Chip
                Label={label}
                Size={isActive ? 'L' : 'M'}
                Icon={isActive}
                pressed={isActive}
                onClick={() => setActive(label)}
              />
              {label === 'Today' && <Tag Label="New" Tone="Positive" />}
            </div>
          );
        })}
      </div>
      <Button Label="Search" onClick={onSearch} />
    </div>
  );
}

